    return remaining if remaining >= 0 else 0

def min_remaining_space(V, n, volumes):
    """Calculate minimum remaining space in a box using 0/1 knapsack DP."""
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in volumes[:n]:
        if vol > V:
            continue
        for s in range(V, vol - 1, -1):
            if dp[s - vol]:
                dp[s] = True
    max_sum = 0
    for s in range(V, -1, -1):
        if dp[s]:
            max_sum = s
            break
    return V - max_sum

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Dynamic programming: dp[cap] = maximum volume that can be packed in capacity 'cap'
    dp = [0] * (V + 1)
    for vol in volumes:
        if vol > V:
            continue
        for cap in range(V, vol - 1, -1):
            possible = dp[cap - vol] + vol
            if possible > dp[cap]:
                dp[cap] = possible
    max_used = dp[V]
    return V - max_used

def calculate_arrangements(n, m, a) -> int:
    mod = 10**6 + 7
    if m == 0:
        return 1
    if sum(a) < m:
        return 0
    dp = [0] * (m + 1)
    dp[0] = 1
    for limit in a:
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j - 1] + dp[j]) % mod
        newdp = [0] * (m + 1)
        for j in range(0, m + 1):
            low = j - limit
            if low > 0:
                newdp[j] = (prefix[j] - prefix[low - 1]) % mod
            else:
                newdp[j] = prefix[j] % mod
        dp = newdp
    return dp[m] % mod

def next_permutation(perm: list) -> bool:
    i = len(perm) - 2
    while i >= 0 and perm[i] >= perm[i + 1]:
        i -= 1
    if i == -1:
        perm.reverse()
        return False
    j = len(perm) - 1
    while perm[j] <= perm[i]:
        j -= 1
    perm[i], perm[j] = perm[j], perm[i]
    perm[i + 1:] = perm[i + 1:][::-1]
    return True

